from collections import Counter
def transform_any(grid):
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    marks={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x!=bg}
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    for r in range(h):
        cs=[c for rr,c in marks if rr==r]
        cs.sort()
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b): out[r][c]=3
    for c in range(w):
        rs=[r for r,cc in marks if cc==c]
        rs.sort()
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b): out[r][c]=3
    return out
